CREATE TABLE cases (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT cases_json CHECK (JSON_VALID(data)));
CREATE TABLE case_notes (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT case_notes_json CHECK (JSON_VALID(data)));
CREATE TABLE case_actions (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT case_actions_json CHECK (JSON_VALID(data)));
CREATE TABLE outbox (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT outbox_json CHECK (JSON_VALID(data)));
CREATE TABLE processed_events (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT processed_events_json CHECK (JSON_VALID(data)));
CREATE TABLE idempotency (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT idempotency_json CHECK (JSON_VALID(data)));
ALTER TABLE cases ADD COLUMN evaluation_id VARCHAR(64) GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(data,'$.evaluationId'))) STORED, ADD UNIQUE KEY cases_evaluation (evaluation_id);